const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0, 'utf-8').trim();
    if (!input) return;

    let n = parseInt(input, 10);
    let steps = 0;

    while (n > 0) {
        let temp = n;
        let maxDigit = 0;
        while (temp > 0) {
            const digit = temp % 10;
            if (digit > maxDigit) {
                maxDigit = digit;
            }
            temp = Math.floor(temp / 10);
        }
        n -= maxDigit;
        steps++;
    }

    console.log(steps);
}

solve();
